15	#ifndef TESTS_VERILATOR_SIM_CORALNPU_MEMORY_IF_H_
16	#define TESTS_VERILATOR_SIM_CORALNPU_MEMORY_IF_H_
17	
18	#include <stdint.h>
19	#include <stdio.h>
20	
21	#include <algorithm>
22	#include <map>
23	
24	#include "tests/verilator_sim/sysc_module.h"
25	
26	// A memory model base class
27	struct Memory_if : Sysc_module {
28	  const int kPageSize = 4 * 1024;
29	  const int kPageMask = ~(kPageSize - 1);
30	
31	  struct memory_page_t {
32	    uint32_t addr;
33	    uint8_t  data[4096];
34	  };
35	
36	  Memory_if(sc_module_name n, const char* bin, int limit = -1) :
37	      Sysc_module(n) {
38	    FILE *f = fopen(bin, "rb");
39	
40	    fseek(f, 0, SEEK_END);
41	    int64_t fsize = ftell(f);
42	    fseek(f, 0, SEEK_SET);
43	    uint8_t *fdata = new uint8_t[fsize];
44	
45	    fread(fdata, fsize, 1, f);
46	    fclose(f);
47	
48	    if (limit > 0 && fsize > limit) {
49	      printf("***ERROR Memory_if limit exceeded [%ld > %d]\n", fsize, limit);
50	      exit(-1);
51	    }
52	
53	    int addr = 0;
54	    for (; addr < fsize; addr += kPageSize) {
55	      const int64_t size = std::min(fsize - addr, int64_t(kPageSize));
56	      AddPage(addr, size, fdata + addr);
57	    }
58	    // Create pages for the rest of our memory space, that was not created
59	    // for inserting the binary.
60	    for (; addr < 0x400000; addr += kPageSize) {
61	      AddPage(addr, kPageSize, nullptr);
62	    }
63	
64	    delete [] fdata;
65	  }
66	
67	  bool Read(uint32_t addr, int bytes, uint8_t* data) {
68	    while (bytes > 0) {
69	      const uint32_t maddr = addr & kPageMask;
70	      const uint32_t offset = addr - maddr;
71	      const int limit = kPageSize - offset;
72	      const int len = std::min(bytes, limit);
73	
74	      if (!HasPage(maddr)) {
75	        return false;
76	      }
77	
78	      auto& p = page_[maddr];
79	      uint8_t* d = p.data;
80	      memcpy(data, d + offset, len);
81	#if 0
82	      printf("READ  %08x", addr);
83	      for (int i = 0; i < len; i++) {
84	        printf(" %02x", data[i]);
85	      }
86	      printf("\n");
87	#endif
88	      addr += len;
89	      data += len;
90	      bytes -= len;
91	      assert(bytes >= 0);
92	    }
93	    return true;
94	  }
95	
96	  bool Write(uint32_t addr, int bytes, const uint8_t* data) {
97	    while (bytes > 0) {
98	      const uint32_t maddr = addr & kPageMask;
99	      const uint32_t offset = addr - maddr;
100	      const int limit = kPageSize - offset;
101	      const int len = std::min(bytes, limit);
102	
103	      if (!HasPage(maddr)) {
104	        return false;
105	      }
106	
107	      auto& p = page_[maddr];
108	      uint8_t* d = p.data;
109	      memcpy(d + offset, data, len);
110	#if 0
111	      printf("WRITE %08x", addr);
112	      for (int i = 0; i < len; i++) {
113	        printf(" %02x", data[i]);
114	      }
115	      printf("\n");
116	#endif
117	      addr += len;
118	      data += len;
119	      bytes -= len;
120	      assert(bytes >= 0);
121	    }
122	    return true;
123	  }
124	
125	 protected:
126	  void ReadSwizzle(const uint32_t addr, const int bytes, uint8_t* data) {
127	    const int mask = bytes - 1;
128	    const int alignment = (bytes - (addr & mask)) & mask;  // left shuffle
129	    uint8_t tmp[512/8];
130	
131	    if (!alignment) return;
132	
133	    for (int i = 0; i < bytes; ++i) {
134	      tmp[i] = data[i];
135	    }
136	
137	    for (int i = 0; i < bytes; ++i) {
138	      data[i] = tmp[(i + alignment) & mask];
139	    }
140	  }
141	
142	  void WriteSwizzle(const uint32_t addr, const int bytes, uint8_t* data) {
143	    const int mask = bytes - 1;
144	    const int alignment = addr & mask;  // right shuffle
145	    uint8_t tmp[512/8];
146	
147	    if (!alignment) return;
148	
149	    for (int i = 0; i < bytes; ++i) {
150	      tmp[i] = data[i];
151	    }
152	
153	    for (int i = 0; i < bytes; ++i) {
154	      data[i] = tmp[(i + alignment) & mask];
155	    }
156	  }
157	
158	 private:
159	  std::map<uint32_t, memory_page_t> page_;
160	
161	  bool HasPage(const uint32_t addr) {
162	    return page_.find(addr) != page_.end();
163	  }
164	
165	  void AddPage(const uint32_t addr, const int bytes,
166	               const uint8_t* data = nullptr) {
167	    const uint32_t addrbase = addr & kPageMask;
168	    if (addr != addrbase) {
169	      printf("AddPage(%08x, %d)\n", addr, bytes);
170	      assert(false && "AddPage: address not page aligned");
171	    }
172	
173	    if (HasPage(addr)) {
174	      printf("AddPage(%08x, %d)\n", addr, bytes);
175	      assert(false && "AddPage: address already populated");
176	    }
177	
178	    auto& p = page_[addr];
179	    uint8_t* d = p.data;
180	
181	    if (bytes < kPageSize || data == nullptr) {
182	#if 1
183	      // remove need for .bss  (hacky?)
184	      memset(d, 0x00, kPageSize);
185	#else
186	      memset(d, 0xcc, kPageSize);
187	#endif
188	    }
189	
190	    if (data) {
191	      memcpy(d, data, bytes);
192	    }
193	  }
194	};
