20	uint32_t LoadElf(uint8_t* data, CopyFn copy_fn) {
21	  const Elf32_Ehdr* elf_header = reinterpret_cast<Elf32_Ehdr*>(data);
22	  for (int i = 0; i < elf_header->e_phnum; ++i) {
23	    const Elf32_Phdr* program_header = reinterpret_cast<Elf32_Phdr*>(
24	        data + elf_header->e_phoff + sizeof(Elf32_Phdr) * i);
25	    if (program_header->p_type != PT_LOAD) {
26	      continue;
27	    }
28	    if (program_header->p_filesz == 0) {
29	      continue;
30	    }
31	    copy_fn(reinterpret_cast<void*>(program_header->p_paddr),
32	            reinterpret_cast<void*>(data + program_header->p_offset),
33	            program_header->p_filesz);
34	  }
35	  return elf_header->e_entry;
36	}
