38	bool LookupSymbol(const uint8_t* data, const std::string& symbol_name, uint32_t* symbol_addr) {
39	  if (symbol_addr == nullptr)
40	    return false;
41	  const Elf32_Ehdr* elf_header = reinterpret_cast<const Elf32_Ehdr*>(data);
42	
43	  // Locate .shstrtab
44	  if (elf_header->e_shstrndx == SHN_UNDEF)
45	    return false;
46	  const Elf32_Half section_string_table_idx = elf_header->e_shstrndx;
47	  const Elf32_Shdr* section_string_table_header = reinterpret_cast<const Elf32_Shdr*>(
48	    data + elf_header->e_shoff + sizeof(Elf32_Shdr) * section_string_table_idx);
49	  const char* section_string_table =
50	    reinterpret_cast<const char*>(data + section_string_table_header->sh_offset);
51	
52	  // Locate .strtab and .symtab
53	  const Elf32_Sym* symbol_table = nullptr;
54	  uint32_t symbol_count;
55	  const char* string_table = nullptr;
56	  for (int i = 0; i < elf_header->e_shnum; ++i) {
57	    const Elf32_Shdr* section_header = reinterpret_cast<const Elf32_Shdr*>(
58	      data + elf_header->e_shoff + sizeof(Elf32_Shdr) * i);
59	    if (section_header->sh_type == SHT_SYMTAB) {
60	      const char* symtab_name = (section_string_table + section_header->sh_name);
61	      const char* expected_symtab_name = ".symtab";
62	      if (strncmp(symtab_name, expected_symtab_name, strlen(expected_symtab_name)) == 0) {
63	        symbol_count = section_header->sh_size / sizeof(Elf32_Sym);
64	        symbol_table = reinterpret_cast<const Elf32_Sym*>(
65	          data + section_header->sh_offset);
66	      }
67	    }
68	    if (section_header->sh_type == SHT_STRTAB) {
69	      const char* strtab_name = (section_string_table + section_header->sh_name);
70	      const char* expected_strtab_name = ".strtab";
71	      if (strncmp(strtab_name, expected_strtab_name, strlen(expected_strtab_name)) == 0) {
72	        string_table = reinterpret_cast<const char*>(data + section_header->sh_offset);
73	      }
74	    }
75	  }
76	  if (string_table == nullptr || symbol_table == nullptr)
77	    return false;
78	
79	  // Find our symbol!
80	  for (uint32_t i = 0; i < symbol_count; ++i) {
81	    const Elf32_Sym* symbol = symbol_table + i;
82	    if (symbol->st_name != 0) {
83	      const char* found_symbol_name = string_table + symbol->st_name;
84	      if (strcmp(found_symbol_name, symbol_name.c_str()) == 0) {
85	        *symbol_addr = symbol->st_value;
86	        return true;
87	      }
88	    }
89	  }
90	  return false;
91	}

