349	int sc_main(int argc, char *argv[]) {
350	  absl::SetProgramUsageMessage("CoralNPU SystemC simulation tool");
351	  auto out_args = absl::ParseCommandLine(argc, argv);
352	  argc = out_args.size();
353	  argv = &out_args[0];
354	  if (argc != 2) {
355	    fprintf(stderr, "Need one binary input file\n");
356	    return 1;
357	  }
358	  const char* path = argv[1];
359	
360	  Core_run(Sysc_tb::get_name(argv[0]), path, absl::GetFlag(FLAGS_cycles),
361	           absl::GetFlag(FLAGS_trace));
362	  return 0;
363	}
