47	                               std::optional<std::function<void()>> halted_cb)
48	    : Sysc_tb(n, loops, random),
49	      tg_("traffic_generator"),
50	      tlm2axi_bridge_("tlm2axi_bridge"),
51	      tlm_mux_("tlm_mux"),
52	      tohost_initiator_socket_("tohost_initiator_socket"),
53	      axi2tlm_bridge_("axi2tlm_bridge"),
54	      tlm2axi_checker_("tlm2axi_checker"),
55	      tlm2axi_signals_("tlm2axi_signals"),
56	      axi2tlm_signals_("axi2tlm_signals"),
57	      xbar_("xbar"),
58	      wfi_cb_(wfi_cb),
59	      halted_cb_(halted_cb),
60	      instr_trace_(instr_trace),
61	      backdoor_load_(backdoor_load) {
62	  if (CoreMiniAxi_tb::singleton_ != nullptr) {
63	    CHECK(false);
64	  }
65	  CoreMiniAxi_tb::singleton_ = this;
66	  core_ = std::make_unique<VERILATOR_MODEL>("core");
