74	  // TLM2AXI
75	  tlm2axi_bridge_.clk(clock);
76	  tlm2axi_bridge_.resetn(resetn);
77	  // AXI Protocol checker
78	  tlm2axi_checker_.clk(clock);
79	  tlm2axi_checker_.resetn(resetn);
80	
81	  // AXI2TLM
82	  axi2tlm_bridge_.clk(clock);
83	  axi2tlm_bridge_.resetn(resetn);
84	
85	  tlm2axi_signals_.connect(tlm2axi_bridge_);
86	  tlm2axi_signals_.connect(tlm2axi_checker_);
87	  axi2tlm_signals_.connect(axi2tlm_bridge_);
88	
89	  Connect();
90	
91	  SC_HAS_PROCESS(CoreMiniAxi_tb);
92	  SC_THREAD(tohost_reader_thread);
93	
94	  tg_.setStartDelay(sc_time(5, SC_NS));
95	  if (debug_axi) {
96	    tg_.enableDebug();
97	  }
98	
99	  axi2tlm_bridge_.socket.bind(xbar_.socket());
