314	absl::Status CoreMiniAxi_tb::LoadElfAsync(const std::string& file_name) {
315	  absl::MutexLock lock(&transfer_queue_mtx_);
316	  int fd = open(file_name.c_str(), 0);
317	  CHECK(fd > 0);
318	  struct stat sb;
319	  CHECK(fstat(fd, &sb) == 0);
320	  auto file_size = sb.st_size;
321	  auto file_data = mmap(nullptr, file_size, PROT_READ, MAP_PRIVATE, fd, 0);
322	  CHECK(file_data != MAP_FAILED);
323	  close(fd);
324	
325	  uint32_t elf_magic = 0x464c457f;
326	  uint8_t* data8 = reinterpret_cast<uint8_t*>(file_data);
327	  if (memcmp(file_data, &elf_magic, sizeof(elf_magic)) == 0) {
328	    std::vector<DataTransfer> elf_transfers;
329	    const Elf32_Ehdr* elf_header = reinterpret_cast<Elf32_Ehdr*>(file_data);
330	    auto entry_point = elf_header->e_entry;
331	    // Reserve space for write+read+expect for each section, and one additional
332	    // for the entry point CSR.
333	    elf_transfers.reserve(3 * elf_header->e_phnum + 1);
334	    ::LoadElf(data8,
335	              [this, &elf_transfers](void* dest, const void* src, size_t count) {
336	                uint64_t addr = reinterpret_cast<uint64_t>(dest);
337	                uint32_t itcm_size = KP_itcmSizeKBytes * 1024;
338	                uint32_t dtcm_size = KP_dtcmSizeKBytes * 1024;
339	                uint32_t dtcm_base = (KP_itcmSizeKBytes == 8 && KP_dtcmSizeKBytes == 32) ? 0x10000 : 0x100000;
340	                bool in_tcm = (addr < itcm_size) || (addr >= dtcm_base && addr < dtcm_base + dtcm_size);
341	
342	                bool use_backdoor = this->backdoor_load_;
343	                if (use_backdoor && in_tcm) {
344	                  this->BackdoorLoad(addr, reinterpret_cast<const uint8_t*>(src), count);
345	                } else {
346	                  elf_transfers.push_back(utils::Write(
347	                      reinterpret_cast<uint64_t>(dest),
348	                      reinterpret_cast<uint8_t*>(const_cast<void*>(src)), count));
349	                  elf_transfers.push_back(
350	                      utils::Read(reinterpret_cast<uint64_t>(dest), count));
351	                  elf_transfers.push_back(utils::Expect(
352	                      reinterpret_cast<uint8_t*>(const_cast<void*>(src)), count));
353	                }
354	                return dest;
355	              });
356	    elf_transfers.push_back(utils::Write(
357	      csr_addr_ + 0x4, reinterpret_cast<uint8_t*>(&entry_point), sizeof(entry_point)
358	    ));
359	    transfer_queue_.push(
360	        std::make_unique<TrafficDesc>(utils::merge(elf_transfers)));
361	    uint32_t tohost;
362	    if (::LookupSymbol(data8, "tohost", &tohost)) {
363	      // NB: This alignment requirement is to simplify the watchpoint implementation.
364	      CHECK((tohost & 0xFFFFFFF0L) == tohost);
365	      tohost_addr_ = tohost;
366	    }
367	    uint32_t tohost_ready;
368	    if (::LookupSymbol(data8, "tohost_ready", &tohost_ready)) {
369	      tohost_ready_addr_ = tohost_ready;
370	    }
371	    uint32_t fromhost;
372	    if (::LookupSymbol(data8, "fromhost", &fromhost)) {
373	      fromhost_addr_ = fromhost;
374	    }
375	    uint32_t fromhost_ready;
376	    if (::LookupSymbol(data8, "fromhost_ready", &fromhost_ready)) {
377	      fromhost_ready_addr_ = fromhost_ready;
378	    }
379	  } else {
380	    // Transaction to fill ITCM with the provided binary.
381	    transfer_queue_.push(
382	        std::make_unique<TrafficDesc>(utils::merge(std::vector<DataTransfer>(
383	            {utils::Write(0, data8, file_size), utils::Read(0, file_size),
384	             utils::Expect(data8, file_size)}))));
385	  }
386	  munmap(file_data, file_size);
387	  return absl::OkStatus();
388	}
