443	void CoreMiniAxi_tb::TraceInstructions() {
444	#define TRACE_INSTRUCTION(x) do { \
445	  uint32_t pc, inst, idx; \
446	  pc = debug_io_.rb_inst_##x##_bits_pc.read().get_word(0); \
447	  inst = debug_io_.rb_inst_##x##_bits_inst.read().get_word(0); \
448	  idx = debug_io_.rb_inst_##x##_bits_idx.read().get_word(0); \
449	  bool trap = debug_io_.rb_inst_##x##_bits_trap.read(); \
450	  if (debug_io_.rb_inst_##x##_valid.read()) { \
451	    auto data = debug_io_.rb_inst_##x##_bits_data.read(); \
452	    std::vector<uint8_t> data_vec(data.length() / 8); \
453	    int num_words = data.length() / 32; \
454	    for (int i = 0; i < num_words; ++i) { \
455	      uint32_t word = data.get_word((num_words - 1) - i); \
456	      data_vec[i*4+0] = (word >> 24) & 0xff; \
457	      data_vec[i*4+1] = (word >> 16) & 0xff; \
458	      data_vec[i*4+2] = (word >> 8) & 0xff; \
459	      data_vec[i*4+3] = word & 0xff; \
460	    } \
461	    tracer_.TraceInstructionRaw(pc, inst, idx, data_vec, trap); \
462	  } \
463	} while (0);
464	REPEAT(TRACE_INSTRUCTION, KP_retirementBufferSize);
465	#undef TRACE_INSTRUCTION
466	}
