468	void CoreMiniAxi_tb::tohost_reader_thread() {
469	  while (true) {
470	    wait(tohost_read_event_);
471	    uint64_t addr = tohost_read_addr_;
472	
473	    tlm::tlm_generic_payload trans;
474	    sc_time delay = SC_ZERO_TIME;
475	
476	    if (addr == 0 && tohost_addr_.has_value()) {
477	      // Triggered by tohost_ready. Read the actual payload from tohost.
478	      uint64_t tohost_payload = 0;
479	      trans.set_command(tlm::TLM_READ_COMMAND);
480	      trans.set_address(tohost_addr_.value());
481	      trans.set_data_ptr(reinterpret_cast<uint8_t*>(&tohost_payload));
482	      trans.set_data_length(8);
483	      trans.set_streaming_width(8);
484	      trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
485	      delay = SC_ZERO_TIME;
486	      tohost_initiator_socket_->b_transport(trans, delay);
487	
488	      if (tohost_payload & 1) {
489	        tohost_halt = true;
490	        tohost_val = static_cast<uint32_t>(tohost_payload);
491	        continue;
492	      }
493	      addr = tohost_payload;
494	    }
495	
496	    if (addr == 0) continue;
497	
498	    uint8_t data[64];
499	
500	    trans.set_command(tlm::TLM_READ_COMMAND);
501	    trans.set_address(addr);
502	    trans.set_data_ptr(data);
503	    trans.set_data_length(64);
504	    trans.set_streaming_width(64);
505	    trans.set_byte_enable_ptr(nullptr);
506	    trans.set_dmi_allowed(false);
507	    trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
508	
509	    tohost_initiator_socket_->b_transport(trans, delay);
510	
511	    uint64_t resp_val = 0;
512	    if (trans.is_response_error()) {
513	      LOG(ERROR) << "tohost read error at " << std::hex << addr << ": " << trans.get_response_string();
514	    } else {
515	      // Clear tohost to acknowledge receipt of the address.
516	      if (tohost_addr_.has_value()) {
517	        uint64_t zero64 = 0;
518	        trans.set_command(tlm::TLM_WRITE_COMMAND);
519	        trans.set_address(tohost_addr_.value());
520	        trans.set_data_ptr(reinterpret_cast<uint8_t*>(&zero64));
521	        trans.set_data_length(8);
522	        trans.set_streaming_width(8);
523	        trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
524	        delay = SC_ZERO_TIME;
525	        tohost_initiator_socket_->b_transport(trans, delay);
526	      }
527	
528	      uint64_t words[8];
529	      memcpy(words, data, sizeof(words));
530	      switch (words[0]) {
531	        case 56:  // sys_openat
532	        {
533	          int64_t dirfd_guest = static_cast<int64_t>(words[1]);
534	          int dirfd = (dirfd_guest == -100) ? AT_FDCWD : static_cast<int>(dirfd_guest);
535	          auto iter = fd_map_.find(words[1]);
536	          if (iter != fd_map_.end()) {
537	            dirfd = iter->second;
538	          }
539	          uint64_t name_addr = words[2];
540	          size_t name_len = static_cast<size_t>(words[3]);
541	          int flags = static_cast<int>(words[4]);
542	          int mode = static_cast<int>(words[5]);
543	
544	          std::vector<char> name(name_len + 1, 0);
545	          trans.set_command(tlm::TLM_READ_COMMAND);
546	          trans.set_address(name_addr);
547	          trans.set_data_ptr(reinterpret_cast<uint8_t*>(name.data()));
548	          trans.set_data_length(name_len);
549	          trans.set_streaming_width(name_len);
550	          trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
551	          delay = SC_ZERO_TIME;
552	          tohost_initiator_socket_->b_transport(trans, delay);
553	          if (trans.is_response_error()) {
554	            resp_val = -1;
555	          } else {
556	            int host_flags = 0;
557	            if (flags & 0x0001) host_flags |= O_WRONLY;
558	            if (flags & 0x0002) host_flags |= O_RDWR;
559	            if (flags & 0x0200) host_flags |= O_CREAT;
560	            if (flags & 0x0400) host_flags |= O_TRUNC;
561	            if (flags & 0x0800) host_flags |= O_EXCL;
562	            if (flags & 0x4000) host_flags |= O_APPEND;
563	
564	            int host_fd = openat(dirfd, name.data(), host_flags, mode);
565	            if (host_fd >= 0) {
566	              resp_val = host_fd + 3; // Offset to avoid overlapping with stdio
567	              fd_map_[resp_val] = host_fd;
568	            } else {
569	              resp_val = -1;
570	            }
571	          }
572	        } break;
573	
574	        case 57:  // sys_close
575	        {
576	          uint64_t guest_fd = words[1];
577	          auto iter = fd_map_.find(guest_fd);
578	          if (iter != fd_map_.end()) {
579	            resp_val = close(iter->second);
580	            fd_map_.erase(iter);
581	          } else {
582	            resp_val = -1;
583	          }
584	        } break;
585	
586	        case 62:  // sys_lseek
587	        {
588	          uint64_t guest_fd = words[1];
589	          auto iter = fd_map_.find(guest_fd);
590	          int host_fd = (iter == fd_map_.end()) ? -1 : iter->second;
591	          off_t offset = static_cast<off_t>(words[2]);
592	          int whence = static_cast<int>(words[3]);
593	          resp_val = lseek(host_fd, offset, whence);
594	        } break;
595	
596	        case 63:  // sys_read
597	        {
598	          uint64_t guest_fd = words[1];
599	          uint64_t buf_addr = words[2];
600	          size_t buf_len = static_cast<size_t>(words[3]);
601	          std::vector<uint8_t> buf(buf_len);
602	          ssize_t bytes_read;
603	          if (guest_fd == 0) {
604	            bytes_read = read(0, buf.data(), buf_len);
605	          } else {
606	            auto iter = fd_map_.find(guest_fd);
607	            int host_fd = (iter == fd_map_.end()) ? -1 : iter->second;
608	            bytes_read = read(host_fd, buf.data(), buf_len);
609	          }
610	
611	          if (bytes_read > 0) {
612	            trans.set_command(tlm::TLM_WRITE_COMMAND);
613	            trans.set_address(buf_addr);
614	            trans.set_data_ptr(buf.data());
615	            trans.set_data_length(bytes_read);
616	            trans.set_streaming_width(bytes_read);
617	            trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
618	            delay = SC_ZERO_TIME;
619	            tohost_initiator_socket_->b_transport(trans, delay);
620	            if (trans.is_response_error()) {
621	              LOG(ERROR) << "sys_read buf write error at " << std::hex << buf_addr;
622	              resp_val = -1;
623	            } else {
624	              resp_val = bytes_read;
625	            }
626	          } else {
627	            resp_val = bytes_read;
628	          }
629	        } break;
630	
631	        case 64:  // sys_write
632	        {
633	          uint64_t guest_fd = words[1];
634	          uint64_t buf_addr = words[2];
635	          size_t buf_len = static_cast<size_t>(words[3]);
636	          std::vector<uint8_t> buf(buf_len);
637	          trans.set_command(tlm::TLM_READ_COMMAND);
638	          trans.set_address(buf_addr);
639	          trans.set_data_ptr(buf.data());
640	          trans.set_data_length(buf_len);
641	          trans.set_streaming_width(buf_len);
642	          trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
643	          delay = SC_ZERO_TIME;
644	          tohost_initiator_socket_->b_transport(trans, delay);
645	          if (trans.is_response_error()) {
646	            LOG(ERROR) << "sys_write buf read error at " << std::hex << buf_addr;
647	            resp_val = -1;
648	          } else {
649	            if (guest_fd == 1 || guest_fd == 2) {
650	              std::string s(reinterpret_cast<char*>(buf.data()), buf_len);
651	              std::cout << s << std::flush;
652	              resp_val = buf_len;
653	            } else {
654	              auto iter = fd_map_.find(guest_fd);
655	              int host_fd = (iter == fd_map_.end()) ? -1 : iter->second;
656	              resp_val = write(host_fd, buf.data(), buf_len);
657	            }
658	          }
659	        } break;
660	
661	        case 67:  // sys_pread
662	        {
663	          uint64_t guest_fd = words[1];
664	          auto iter = fd_map_.find(guest_fd);
665	          int host_fd = (iter == fd_map_.end()) ? -1 : iter->second;
666	          uint64_t buf_addr = words[2];
667	          size_t buf_len = static_cast<size_t>(words[3]);
668	          off_t offset = static_cast<off_t>(words[4]);
669	          std::vector<uint8_t> buf(buf_len);
670	          ssize_t bytes_read = pread(host_fd, buf.data(), buf_len, offset);
671	          if (bytes_read > 0) {
672	            trans.set_command(tlm::TLM_WRITE_COMMAND);
673	            trans.set_address(buf_addr);
674	            trans.set_data_ptr(buf.data());
675	            trans.set_data_length(bytes_read);
676	            trans.set_streaming_width(bytes_read);
677	            trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
678	            delay = SC_ZERO_TIME;
679	            tohost_initiator_socket_->b_transport(trans, delay);
680	            if (trans.is_response_error()) {
681	              LOG(ERROR) << "sys_pread buf write error at " << std::hex << buf_addr;
682	              resp_val = -1;
683	            } else {
684	              resp_val = bytes_read;
685	            }
686	          } else {
687	            resp_val = bytes_read;
688	          }
689	        } break;
690	
691	        case 68:  // sys_pwrite
692	        {
693	          uint64_t guest_fd = words[1];
694	          auto iter = fd_map_.find(guest_fd);
695	          int host_fd = (iter == fd_map_.end()) ? -1 : iter->second;
696	          uint64_t buf_addr = words[2];
697	          size_t buf_len = static_cast<size_t>(words[3]);
698	          off_t offset = static_cast<off_t>(words[4]);
699	          std::vector<uint8_t> buf(buf_len);
700	          trans.set_command(tlm::TLM_READ_COMMAND);
701	          trans.set_address(buf_addr);
702	          trans.set_data_ptr(buf.data());
703	          trans.set_data_length(buf_len);
704	          trans.set_streaming_width(buf_len);
705	          trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
706	          delay = SC_ZERO_TIME;
707	          tohost_initiator_socket_->b_transport(trans, delay);
708	          if (trans.is_response_error()) {
709	            LOG(ERROR) << "sys_pwrite buf read error at " << std::hex << buf_addr;
710	            resp_val = -1;
711	          } else {
712	            resp_val = pwrite(host_fd, buf.data(), buf_len, offset);
713	          }
714	        } break;
715	
716	        case 93:  // sys_exit
717	          tohost_halt = true;
718	          tohost_val = words[1];
719	          break;
720	
721	        case 2011:  // sys_getmainvars
722	        {
723	          uint64_t buf_addr = words[1];
724	          uint64_t limit = words[2];
725	          uint64_t argc = 1;
726	          const char* arg0 = "coralnpu.elf";
727	          uint64_t arg0_addr = buf_addr + 16; // Place string after argc and argv[0] pointer
728	          std::vector<uint64_t> packet(2);
729	          packet[0] = argc;
730	          packet[1] = arg0_addr;
731	          if (limit >= (16 + strlen(arg0) + 1)) {
732	            // Write argc and argv pointers
733	            trans.set_command(tlm::TLM_WRITE_COMMAND);
734	            trans.set_address(buf_addr);
735	            trans.set_data_ptr(reinterpret_cast<uint8_t*>(packet.data()));
736	            trans.set_data_length(16);
737	            trans.set_streaming_width(16);
738	            trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
739	            delay = SC_ZERO_TIME;
740	            tohost_initiator_socket_->b_transport(trans, delay);
741	
742	            // Write the string
743	            trans.set_command(tlm::TLM_WRITE_COMMAND);
744	            trans.set_address(arg0_addr);
745	            trans.set_data_ptr(reinterpret_cast<uint8_t*>(const_cast<char*>(arg0)));
746	            trans.set_data_length(strlen(arg0) + 1);
747	            trans.set_streaming_width(strlen(arg0) + 1);
748	            trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
749	            tohost_initiator_socket_->b_transport(trans, delay);
750	
751	            resp_val = 0; // Success
752	          } else {
753	            resp_val = -1;
754	          }
755	        } break;
756	
757	        default:
758	          resp_val = -1;
759	          break;
760	      }
761	    }
762	
763	    // Write return code back to the first word of the packet.
764	    // Use 32-bit writes to be safe with the 32-bit core's bus.
765	    uint32_t resp_low = static_cast<uint32_t>(resp_val);
766	    uint32_t resp_high = static_cast<uint32_t>(resp_val >> 32);
767	
768	    trans.set_command(tlm::TLM_WRITE_COMMAND);
769	    trans.set_address(addr);
770	    trans.set_data_ptr(reinterpret_cast<uint8_t*>(&resp_low));
771	    trans.set_data_length(4);
772	    trans.set_streaming_width(4);
773	    trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
774	    delay = SC_ZERO_TIME;
775	    tohost_initiator_socket_->b_transport(trans, delay);
776	
777	    trans.set_address(addr + 4);
778	    trans.set_data_ptr(reinterpret_cast<uint8_t*>(&resp_high));
779	    tohost_initiator_socket_->b_transport(trans, delay);
780	
781	    // Write completion response to fromhost.
782	    if (fromhost_addr_.has_value()) {
783	      // libgloss-htif htif_syscall polls for fromhost != 0.
784	      // After it sees != 0, it clears fromhost.
785	      uint32_t resp_low = 1;
786	      uint32_t resp_high = 0;
787	
788	      trans.set_command(tlm::TLM_WRITE_COMMAND);
789	      trans.set_address(fromhost_addr_.value());
790	      trans.set_data_ptr(reinterpret_cast<uint8_t*>(&resp_low));
791	      trans.set_data_length(4);
792	      trans.set_streaming_width(4);
793	      trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
794	      delay = SC_ZERO_TIME;
795	      tohost_initiator_socket_->b_transport(trans, delay);
796	
797	      trans.set_address(fromhost_addr_.value() + 4);
798	      trans.set_data_ptr(reinterpret_cast<uint8_t*>(&resp_high));
799	      tohost_initiator_socket_->b_transport(trans, delay);
800	    }
801	
802	    if (fromhost_ready_addr_.has_value()) {
803	      uint64_t one64 = 1;
804	      trans.set_command(tlm::TLM_WRITE_COMMAND);
805	      trans.set_address(fromhost_ready_addr_.value());
806	      trans.set_data_ptr(reinterpret_cast<uint8_t*>(&one64));
807	      trans.set_data_length(8);
808	      trans.set_streaming_width(8);
809	      trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
810	      delay = SC_ZERO_TIME;
811	      tohost_initiator_socket_->b_transport(trans, delay);
812	    }
813	
814	    // Clear tohost_ready if present.
815	    if (tohost_ready_addr_.has_value()) {
816	      uint64_t zero64 = 0;
817	      trans.set_command(tlm::TLM_WRITE_COMMAND);
818	      trans.set_address(tohost_ready_addr_.value());
819	      trans.set_data_ptr(reinterpret_cast<uint8_t*>(&zero64));
820	      trans.set_data_length(8);
821	      trans.set_streaming_width(8);
822	      trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
823	      delay = SC_ZERO_TIME;
824	      tohost_initiator_socket_->b_transport(trans, delay);
825	    }
826	  }
827	}
