829	void CoreMiniAxi_tb::posedge() {
830	  const bool core_io_dbus_valid = debug_io_.dbus_valid;
831	  const bool core_io_dbus_write = debug_io_.dbus_bits_write;
832	  const uint32_t core_io_dbus_addr = debug_io_.dbus_bits_addr.read().get_word(0);
833	
834	  // If we have tohost_ready, trigger only when it's written with 1.
835	  if (tohost_ready_addr_.has_value() && core_io_dbus_valid && core_io_dbus_write && (core_io_dbus_addr == tohost_ready_addr_.value())) {
836	    const uint32_t wdata0 = debug_io_.dbus_bits_wdata.read().get_word(0);
837	    if (wdata0 != 1) return;
838	
839	    // We trigger the read event, which will read from 'tohost' symbol address.
840	    // The tohost_reader_thread already uses tohost_read_addr_ which we should update here.
841	    // Wait, the tohost_reader_thread uses tohost_read_addr_ set in posedge.
842	    // We need to READ the current value of tohost from memory.
843	    // But posedge() shouldn't do bus transactions.
844	    // Let's modify tohost_reader_thread to read tohost if it's not provided.
845	    tohost_read_addr_ = 0; // Signal to thread to read 'tohost' from its known address
846	    tohost_read_event_.notify();
847	    return;
848	  }
849	
850	  // Fallback/Legacy support: trigger on tohost write if tohost_ready is not present.
851	  if (!tohost_ready_addr_.has_value() && tohost_addr_.has_value() && core_io_dbus_valid && core_io_dbus_write && (core_io_dbus_addr == tohost_addr_.value())) {
852	    const uint32_t wdata0 = debug_io_.dbus_bits_wdata.read().get_word(0);
853	    if (wdata0 == 0) return;
854	    if (wdata0 & 1) {
855	      tohost_halt = true;
856	      tohost_val = wdata0;
857	    } else {
858	      tohost_read_addr_ = wdata0;
859	      tohost_read_event_.notify();
860	    }
861	  }
862	
863	  if (instr_trace_) {
864	    TraceInstructions();
865	  }
866	
867	  static bool invoked_halted_cb = false;
868	  if ((io_halted || io_fault || tohost_halt) && !invoked_halted_cb) {
869	    // If instruction tracing is enabled,
870	    // print the data about the instruction trace.
871	    if (instr_trace_) {
872	      tracer_.PrintTrace();
873	    }
874	    invoked_halted_cb = true;
875	    if (halted_cb_) {
876	      halted_cb_.value()();
877	    }
878	  }
879	
880	  static bool wfi_seen = false;
881	  if (io_wfi && !wfi_seen) {
882	    io_irq = true;
883	    wfi_seen = true;
884	    if (wfi_cb_) {
885	      wfi_cb_.value()();
886	    }
887	  } else if (!io_wfi && wfi_seen) {
888	    io_irq = false;
889	    wfi_seen = false;
890	  } else {
891	    io_irq = false;
892	  }
893	
894	
895	  if (!transfer_in_progress_) {
896	    absl::MutexLock lock(&transfer_queue_mtx_);
897	    if (!transfer_queue_.empty()) {
898	      ITrafficDesc* transfer = transfer_queue_.front().get();
899	      tg_.addTransfers(transfer, 0, CoreMiniAxi_tb::axi_transaction_done_cb);
900	      transfer_in_progress_ = true;
901	    }
902	  }
903	}
